package io.github.clean_energy_tools.openadr_3_types.model;

import com.fasterxml.jackson.annotation.JsonProperty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * Demo Program class to demonstrate correct package structure and naming.
 * This would be generated by OpenAPI Generator from the specification.
 */
public class DemoProgram {
    
    @JsonProperty("id")
    @NotNull
    @Size(min = 1)
    private String id;
    
    @JsonProperty("program_name")
    @NotNull
    @Size(min = 1)
    private String programName;
    
    @JsonProperty("retailer_name")
    @NotNull
    @Size(min = 1)
    private String retailerName;
    
    @JsonProperty("country")
    @NotNull
    @Size(min = 2, max = 2)
    private String country;
    
    @JsonProperty("program_type")
    @NotNull
    private DemoProgramType programType;
    
    // Constructors
    public DemoProgram() {}
    
    public DemoProgram(String id, String programName, String retailerName, String country, DemoProgramType programType) {
        this.id = id;
        this.programName = programName;
        this.retailerName = retailerName;
        this.country = country;
        this.programType = programType;
    }
    
    // Getters and Setters
    public String getId() { return id; }
    public void setId(String id) { this.id = id; }
    
    public String getProgramName() { return programName; }
    public void setProgramName(String programName) { this.programName = programName; }
    
    public String getRetailerName() { return retailerName; }
    public void setRetailerName(String retailerName) { this.retailerName = retailerName; }
    
    public String getCountry() { return country; }
    public void setCountry(String country) { this.country = country; }
    
    public DemoProgramType getProgramType() { return programType; }
    public void setProgramType(DemoProgramType programType) { this.programType = programType; }
    
    // Fluent API methods
    public DemoProgram id(String id) {
        this.id = id;
        return this;
    }
    
    public DemoProgram programName(String programName) {
        this.programName = programName;
        return this;
    }
    
    public DemoProgram retailerName(String retailerName) {
        this.retailerName = retailerName;
        return this;
    }
    
    public DemoProgram country(String country) {
        this.country = country;
        return this;
    }
    
    public DemoProgram programType(DemoProgramType programType) {
        this.programType = programType;
        return this;
    }
}